/**
 * First and last name on one page, with an OPTIONAL profile photo from the gallery or the files: the first box is focused as the
 * page opens; a mistake is read out as a live region. The photo can be skipped, changed or removed; Continue never needs one.
 */
@Composable
private fun NamePage(
    first: String,
    last: String,
    onFirst: (String) -> Unit,
    onLast: (String) -> Unit,
    photo: Bitmap?,
    photoError: String?,
    onPickPhoto: () -> Unit,
    onRemovePhoto: () -> Unit,
    onContinue: () -> Unit,
    onBack: () -> Unit
) {
    var error by remember { mutableStateOf<String?>(null) }
    val focus = remember { FocusRequester() }
    val lastFocus = remember { FocusRequester() }
    LaunchedEffect(Unit) {
        try {
            focus.requestFocus()
        } catch (e: Exception) {
            // The box was not on screen yet; the player can still tap it.
        }
    }
    fun clean(s: String): Boolean = s.isNotBlank() && s.all { it.isLetter() || it == ' ' || it == '-' || it == '\'' }
    val submit: () -> Unit = {
        error = when {
            !clean(first) -> "Please type your first name, using letters only."
            !clean(last) -> "Please type your last name, using letters only."
            else -> null
        }
        if (error == null) onContinue()
    }
    BackHandler(onBack = onBack)
    PageColumn {
        BackButton(onBack)
        Spacer(modifier = Modifier.height(16.dp))
        PageHeading("Your name")
        Spacer(modifier = Modifier.height(8.dp))
        Text("Type your first name and your last name. A profile photo is optional.", style = MaterialTheme.typography.bodyLarge)
        Spacer(modifier = Modifier.height(16.dp))
        OutlinedTextField(
            value = first,
            onValueChange = { error = null; onFirst(it.take(CareerWorld.MAX_NAME_LENGTH)) },
            label = { Text("First name") },
            singleLine = true,
            isError = error != null && !clean(first),
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text, imeAction = ImeAction.Next),
            keyboardActions = KeyboardActions(onNext = { try { lastFocus.requestFocus() } catch (e: Exception) { } }),
            modifier = Modifier.fillMaxWidth().focusRequester(focus)
        )
        Spacer(modifier = Modifier.height(12.dp))
        OutlinedTextField(
            value = last,
            onValueChange = { error = null; onLast(it.take(CareerWorld.MAX_NAME_LENGTH)) },
            label = { Text("Last name") },
            singleLine = true,
            isError = error != null && clean(first) && !clean(last),
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text, imeAction = ImeAction.Done),
            keyboardActions = KeyboardActions(onDone = { submit() }),
            modifier = Modifier.fillMaxWidth().focusRequester(lastFocus)
        )
        error?.let {
            Spacer(modifier = Modifier.height(8.dp))
            Text(
                text = it,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.error,
                modifier = Modifier.semantics { liveRegion = LiveRegionMode.Assertive }
            )
        }
        Spacer(modifier = Modifier.height(20.dp))
        Text("Profile photo (optional)", style = MaterialTheme.typography.titleMedium)
        Spacer(modifier = Modifier.height(4.dp))
        Text(
            text = if (photo == null) "You can add a photo from your gallery or your files, or skip this." else "Your photo is chosen.",
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
        if (photo != null) {
            Spacer(modifier = Modifier.height(8.dp))
            Image(bitmap = photo.asImageBitmap(), contentDescription = "Your profile photo", modifier = Modifier.size(120.dp))
        }
        Spacer(modifier = Modifier.height(8.dp))
        OutlinedButton(onClick = onPickPhoto, modifier = Modifier.fillMaxWidth().heightIn(min = 56.dp)) {
            Text(if (photo == null) "Choose a profile photo" else "Choose a different photo")
        }
        if (photo != null) {
            Spacer(modifier = Modifier.height(8.dp))
            OutlinedButton(onClick = onRemovePhoto, modifier = Modifier.fillMaxWidth().heightIn(min = 56.dp)) { Text("Remove the photo") }
        }
        photoError?.let {
            Spacer(modifier = Modifier.height(8.dp))
            Text(
                text = it,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.error,
                modifier = Modifier.semantics { liveRegion = LiveRegionMode.Assertive }
            )
        }
        Spacer(modifier = Modifier.height(16.dp))
        Button(onClick = { submit() }, modifier = Modifier.fillMaxWidth().heightIn(min = 56.dp)) { Text("Continue") }
    }
}

/** The career's profile photo, when it has one: decoration with a description, shown above the details. */
@Composable
internal fun CareerPhoto(career: CareerProfile) {
    val context = LocalContext.current
    val image = remember(career.id, career.hasPhoto) {
        if (career.hasPhoto) BitmapFactory.decodeFile(photoFile(context, career.id).path)?.asImageBitmap() else null
    }
    if (image != null) {
        Image(bitmap = image, contentDescription = "Profile photo of ${career.fullName}", modifier = Modifier.size(120.dp))
        Spacer(modifier = Modifier.height(12.dp))
    }
}

private fun photoFile(context: Context, id: String): File = File(File(context.applicationContext.filesDir, "career_photos"), "$id.png")

/** Reads the picked picture and shrinks it (longest side 384 pixels): a profile photo needs no more. */
private fun loadPhoto(context: Context, uri: Uri): Bitmap? = try {
    val resolver = context.contentResolver
    val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
    resolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, bounds) }
    var sample = 1
    while (bounds.outWidth / sample > 768 || bounds.outHeight / sample > 768) sample *= 2
    val opts = BitmapFactory.Options().apply { inSampleSize = sample }
    val raw = resolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, opts) }
    if (raw == null) {
        null
    } else {
        val scale = 384f / maxOf(raw.width, raw.height)
        if (scale < 1f) {
            Bitmap.createScaledBitmap(raw, (raw.width * scale).toInt().coerceAtLeast(1), (raw.height * scale).toInt().coerceAtLeast(1), true)
        } else raw
    }
} catch (e: Exception) {
    null
}

private fun savePhoto(context: Context, id: String, bitmap: Bitmap) {
    try {
        val f = photoFile(context, id)
        f.parentFile?.mkdirs()
        FileOutputStream(f).use { bitmap.compress(Bitmap.CompressFormat.PNG, 100, it) }
    } catch (e: Exception) {
        // The photo is only decoration; the career is saved either way.
    }
}

package com.cricketsim.logic

import kotlin.math.roundToInt

/**
 * Who the selectors pick. The player is ranked against the other players of his district club by one number, his value in
 * his role (a batsman by his batting, a bowler by his bowling, an all-rounder by both). The selectors take the top [cutoff]
 * players, and the career difficulty moves the cutoff: Very easy takes almost everyone, Medium the top eleven, Hard the top nine, Legend the top
 * seven ([CareerWorld.selectionFactor]). Recent form moves the player up or down by as many as three places: the average impact of
 * his last three matches against 25 points, a place for every ten.
 */
object CareerSelection {

    class Decision(
        val selected: Boolean,
        val rank: Int,
        val cutoff: Int,
        val squadSize: Int,
        val formAdjust: Int,
        val reason: String
    )

    private fun value(p: CareerPlayer): Double = when (p.role) {
        "Batsman", "Wicketkeeper-batsman" -> p.batting * 0.8 + p.fielding * 0.2
        "Bowler" -> p.bowling * 0.8 + p.fielding * 0.2
        "Batting all-rounder" -> p.batting * 0.55 + p.bowling * 0.35 + p.fielding * 0.1
        else -> p.bowling * 0.55 + p.batting * 0.35 + p.fielding * 0.1
    }

    private fun ordinal(n: Int): String = when {
        n % 100 in 11..13 -> "${n}th"
        n % 10 == 1 -> "${n}st"
        n % 10 == 2 -> "${n}nd"
        n % 10 == 3 -> "${n}rd"
        else -> "${n}th"
    }

    fun decide(career: CareerProfile): Decision {
        val squad = career.myClub?.players ?: return Decision(true, 1, 11, 15, 0, "")
        val sorted = squad.sortedByDescending { value(it) }
        val rank = sorted.indexOfFirst { it.isUser }.let { if (it < 0) squad.size else it + 1 }
        val factor = CareerWorld.selectionFactor(career.difficulty)
        val cutoff = (11 / factor).roundToInt().coerceIn(5, squad.size)
        val form = career.form.orEmpty().takeLast(3)
        val adjust = if (form.isEmpty()) 0 else ((form.average() - 25.0) / 10.0).roundToInt().coerceIn(-3, 3)
        val selected = rank - adjust <= cutoff
        val formNote = when {
            adjust > 0 -> " Your good form moves you up ${if (adjust == 1) "a place" else "$adjust places"}."
            adjust < 0 -> " Your poor form drops you ${if (adjust == -1) "a place" else "${-adjust} places"}."
            else -> ""
        }
        val base = "You rank ${ordinal(rank)} of ${squad.size} players at your club, and the selectors on ${career.difficulty.lowercase()} take the top $cutoff.$formNote"
        val reason = if (selected) "You are in the XI. $base" else "You are not in the XI. $base Score runs, take wickets or improve your ratings to move up."
        return Decision(selected, rank, cutoff, squad.size, adjust, reason)
    }

    private fun v(p: Player): Double = maxOf(p.battingRating, p.bowlingRating) + p.fieldingRating * 0.1

    /**
     * The player's club squad as the selectors leave it for a match. Not selected: the squad without him. Selected: the club's best
     * eleven, with him in it (in the place of the weakest player of his own kind; the keeper keeps his place unless he is the keeper).
     */
    fun squadForMatch(squad: Team, tags: Map<String, SquadTag>, stadium: Stadium, userPlayerId: String, selected: Boolean): Team {
        val me = squad.players.find { it.id == userPlayerId } ?: return squad
        if (!selected) return squad.copy(players = squad.players.filter { it.id != userPlayerId })
        val best = CplSimulator.pickXI(squad, tags, stadium)
        if (best.players.any { it.id == userPlayerId }) return best
        val others = best.players.filter { it.role != PlayerRole.WICKETKEEPER || me.role == PlayerRole.WICKETKEEPER }
        val sameKind = others.filter { it.role == me.role }
        val victim = (if (sameKind.isEmpty()) others else sameKind).minByOrNull { v(it) } ?: return best
        return best.copy(players = best.players.map { if (it.id == victim.id) me else it })
    }

    /** The eleven the player's club takes the field with for a match he is selected for (captain and keeper set). */
    fun matchXI(squad: Team, tags: Map<String, SquadTag>, stadium: Stadium, userPlayerId: String): Team =
        CplSimulator.pickXI(squadForMatch(squad, tags, stadium, userPlayerId, true), tags, stadium)
}

package com.cricketsim.logic

import kotlin.math.floor
import kotlin.math.roundToInt
import kotlin.random.Random

/**
 * What a match does to the player: his form (the impact points of his last matches) and his ratings. A player who is in the XI grows
 * a little after every match, more after a good one and much more when he is young; a player who is not picked does not grow.
 * Growth is shared between batting, bowling and fielding by his role.
 *
 * Dials: [BASE_GROWTH] (a match of 20 impact points gives about this many rating points to a sixteen-year-old), [IMPACT_PAR]
 * (the impact of an ordinary match).
 */
object CareerProgress {
    const val BASE_GROWTH = 1.0
    const val IMPACT_PAR = 20.0

    class Result(val career: CareerProfile, val text: String)

    private fun gain(g: Double, random: Random): Int {
        val whole = floor(g).toInt()
        return whole + if (random.nextDouble() < g - whole) 1 else 0
    }

    /** [before] and [after] are the player's tournament statistics around the match; they differ only if he played. */
    fun afterMatch(career: CareerProfile, before: PlayerStats?, after: PlayerStats?, random: Random): Result {
        val played = (after?.matches ?: 0) > (before?.matches ?: 0)
        if (after == null || !played) return Result(career, "You were not in the XI for this match.")
        fun d(f: (PlayerStats) -> Int) = f(after) - (before?.let(f) ?: 0)
        val runs = d { it.runs }
        val balls = d { it.balls }
        val wickets = d { it.wickets }
        val conceded = d { it.runsConceded }
        val bowled = d { it.ballsBowled }
        val catches = d { it.catches }
        val impact = after.impact - (before?.impact ?: 0.0)

        val parts = ArrayList<String>()
        if (balls > 0) parts.add("You scored $runs off $balls balls.")
        if (bowled > 0) parts.add("You took $wickets wicket${if (wickets == 1) "" else "s"} for $conceded in ${bowled / 6}.${bowled % 6} overs.")
        if (catches > 0) parts.add("You took $catches catch${if (catches == 1) "" else "es"}.")
        if (parts.isEmpty()) parts.add("You did not bat or bowl.")

        // Growth: more after a good match, more for the young (a sixteen-year-old grows at full speed, a thirty-year-old barely).
        val score = ((impact - IMPACT_PAR) / 40.0).coerceIn(-0.5, 1.5)
        val ageFactor = (31 - career.age).coerceIn(1, 15) / 15.0
        val g = (0.5 + score).coerceAtLeast(0.1) * ageFactor * BASE_GROWTH
        val (batShare, bowlShare) = when (career.role) {
            "Batsman", "Wicketkeeper-batsman" -> 1.0 to 0.08
            "Bowler" -> 0.15 to 1.0
            "Batting all-rounder" -> 0.65 to 0.45
            else -> 0.45 to 0.65
        }
        val batGain = gain(g * batShare, random)
        val bowlGain = gain(g * bowlShare, random)
        val fieldGain = gain(g * 0.2 + catches * 0.3, random)
        val newBat = (career.batting + batGain).coerceAtMost(95)
        val newBowl = (career.bowling + bowlGain).coerceAtMost(95)
        val newField = (career.fielding + fieldGain).coerceAtMost(95)

        val changes = listOfNotNull(
            if (newBat > career.batting) "batting +${newBat - career.batting}" else null,
            if (newBowl > career.bowling) "bowling +${newBowl - career.bowling}" else null,
            if (newField > career.fielding) "fielding +${newField - career.fielding}" else null
        )
        val growth = if (changes.isEmpty()) "Your ratings did not change." else "Your ratings grew: ${changes.joinToString(", ")}."

        val clubs = career.clubs.map { club ->
            if (club.name != career.club) club
            else club.copy(players = club.players.map { if (it.isUser) it.copy(batting = newBat, bowling = newBowl, fielding = newField) else it })
        }
        val updated = career.copy(
            batting = newBat, bowling = newBowl, fielding = newField,
            clubTeams = clubs,
            matchesPlayed = career.matchesPlayed + 1,
            form = (career.form.orEmpty() + impact).takeLast(5)
        )
        return Result(updated, "${parts.joinToString(" ")} Your impact was ${impact.roundToInt()}. $growth")
    }
}
